const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');

const SCRIPT = path.join(__dirname, 'with-rate-limit-retry.sh');

// A fake CLI that fails with `failWith` on its first `failures` calls, then
// prints `ok` to stdout. It counts calls in a file so the test can read them.
function fakeCli(failures, failWith) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'rate-limit-retry-'));
  const counter = path.join(dir, 'calls');
  const cli = path.join(dir, 'fake-vercel');
  fs.writeFileSync(
    cli,
    `#!/usr/bin/env bash
calls=$(( $(cat "${counter}" 2>/dev/null || echo 0) + 1 ))
echo "$calls" > "${counter}"
echo "progress $calls" >&2
if (( calls <= ${failures} )); then
  echo "${failWith}" >&2
  exit 1
fi
echo ok
`,
    { mode: 0o755 }
  );
  return {
    cli,
    calls: () => Number(fs.readFileSync(counter, 'utf8')),
  };
}

function run(cli, env = {}) {
  return spawnSync('bash', [SCRIPT, cli, 'deploy'], {
    encoding: 'utf8',
    env: {
      ...process.env,
      RATE_LIMIT_BASE_DELAY_SECONDS: '0',
      ...env,
    },
  });
}

const RATE_LIMITED =
  'Error: Rate limited. Too many requests to the same endpoint: /teams';

test('retries a rate-limited command until it succeeds', () => {
  const fake = fakeCli(2, RATE_LIMITED);
  const result = run(fake.cli);

  assert.equal(result.status, 0);
  assert.equal(fake.calls(), 3);
  // Only the successful attempt's stdout reaches the caller.
  assert.equal(result.stdout, 'ok\n');
  assert.match(result.stderr, /progress 1\n.*Rate limited/s);
  assert.match(result.stderr, /attempt 2 of 5/);
});

test('does not retry other failures', () => {
  const fake = fakeCli(1, 'Error: Project not found');
  const result = run(fake.cli);

  assert.equal(result.status, 1);
  assert.equal(fake.calls(), 1);
  assert.equal(result.stdout, '');
});

test('gives up after the last attempt with the command status', () => {
  const fake = fakeCli(10, RATE_LIMITED);
  const result = run(fake.cli, { RATE_LIMIT_MAX_ATTEMPTS: '3' });

  assert.equal(result.status, 1);
  assert.equal(fake.calls(), 3);
});

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const test = require('node:test');

const {
  FatalError,
  applyOverrides,
  main,
  resolveTarget,
  selectDeployment,
  waitForDeployment,
} = require('./resolve.js');

const SHA = 'a'.repeat(40);
const BASE_SHA = 'b'.repeat(40);

function deployment(overrides = {}) {
  const { meta, ...rest } = overrides;
  return {
    uid: 'dpl_1',
    url: 'app-abc.labs.vercel.dev',
    inspectorUrl: 'https://vercel.com/team/app/1',
    source: 'git',
    target: null,
    readyState: 'READY',
    createdAt: 1,
    meta: { githubCommitSha: SHA, githubCommitRef: 'feature', ...meta },
    ...rest,
  };
}

function pullRequest(headRef, headSha = SHA) {
  return {
    pull_request: {
      head: { ref: headRef, sha: headSha },
      base: { ref: 'main', sha: BASE_SHA },
    },
  };
}

const previewTarget = { sha: SHA, branch: 'feature', environment: 'preview' };

test('pull requests resolve their head preview deployment', () => {
  assert.deepEqual(
    resolveTarget({
      eventName: 'pull_request',
      event: pullRequest('feature'),
    }),
    previewTarget
  );
});

test('changeset-release PRs resolve the production deployment of their base', () => {
  assert.deepEqual(
    resolveTarget({
      eventName: 'pull_request',
      event: pullRequest('changeset-release/main'),
    }),
    { sha: BASE_SHA, branch: 'main', environment: 'production' }
  );
});

test('pushes to main resolve production; other refs resolve preview', () => {
  assert.deepEqual(
    resolveTarget({ eventName: 'push', githubSha: SHA, githubRefName: 'main' }),
    { sha: SHA, branch: 'main', environment: 'production' }
  );
  assert.deepEqual(
    resolveTarget({
      eventName: 'workflow_dispatch',
      githubSha: SHA,
      githubRefName: 'feature',
    }),
    previewTarget
  );
});

test('overrides replace derived values and are validated', () => {
  assert.deepEqual(
    applyOverrides(previewTarget, {
      sha: BASE_SHA.toUpperCase(),
      environment: 'production',
    }),
    { sha: BASE_SHA, branch: 'feature', environment: 'production' }
  );
  assert.throws(
    () => applyOverrides(previewTarget, { sha: 'abc123' }),
    /full commit SHA/
  );
  assert.throws(
    () => applyOverrides(previewTarget, { environment: 'staging' }),
    /production" or "preview/
  );
});

test('selects only Git deployments and redeploys of the exact commit, branch, and environment', () => {
  const match = deployment({ uid: 'dpl_match' });
  const candidates = [
    deployment({ uid: 'dpl_cli', source: 'cli', createdAt: 9 }),
    deployment({
      uid: 'dpl_other_branch',
      meta: { githubCommitRef: 'feature-candidate-1' },
      createdAt: 9,
    }),
    deployment({ uid: 'dpl_production', target: 'production', createdAt: 9 }),
    deployment({
      uid: 'dpl_other_sha',
      meta: { githubCommitSha: BASE_SHA },
      createdAt: 9,
    }),
    match,
  ];
  assert.equal(selectDeployment(candidates, previewTarget), match);
  const redeploy = deployment({
    uid: 'dpl_redeploy',
    source: 'redeploy',
    createdAt: 2,
  });
  assert.equal(
    selectDeployment([...candidates, redeploy], previewTarget),
    redeploy
  );
  assert.equal(
    selectDeployment(candidates.slice(0, 4), previewTarget),
    undefined
  );
});

test('prefers the newest matching deployment', () => {
  const newer = deployment({ uid: 'dpl_new', createdAt: 2 });
  assert.equal(
    selectDeployment(
      [deployment({ uid: 'dpl_old', readyState: 'CANCELED' }), newer],
      previewTarget
    ),
    newer
  );
});

function respond(next) {
  if (next instanceof Error) {
    throw next;
  }
  return {
    ok: next.status === undefined || next.status < 400,
    status: next.status ?? 200,
    json: async () => next.body ?? { deployments: next.deployments ?? [] },
  };
}

// `responses` answer the per-commit deployment list, in order. `details` maps a
// deployment ID to its v13 record, and `history` is the branch's READY list.
function harness(responses, { details = {}, history = [] } = {}) {
  let clock = 0;
  const requests = [];
  const lookups = [];
  return {
    requests,
    lookups,
    options: {
      projectId: 'prj_1',
      teamId: 'team_1',
      token: 'secret',
      target: previewTarget,
      timeoutMs: 60_000,
      intervalMs: 15_000,
      now: () => clock,
      sleep: async (ms) => {
        clock += ms;
      },
      log: () => {},
      fetchImpl: async (input, init) => {
        const url = new URL(input);
        if (url.pathname.startsWith('/v13/deployments/')) {
          lookups.push(url);
          const uid = decodeURIComponent(url.pathname.split('/').at(-1));
          return respond({ body: details[uid] ?? {} });
        }
        if (url.searchParams.has('branch')) {
          lookups.push(url);
          return respond({ deployments: history });
        }
        requests.push({ url, init });
        return respond(responses.shift());
      },
    },
  };
}

test('polls until the deployment is ready, tolerating transient failures', async () => {
  const { options, requests } = harness([
    { deployments: [] },
    new Error('socket hang up'),
    { status: 503 },
    { status: 429 },
    { deployments: [deployment({ readyState: 'BUILDING' })] },
    { deployments: [deployment()] },
  ]);
  options.timeoutMs = 120_000;
  const result = await waitForDeployment(options);
  assert.equal(result.uid, 'dpl_1');
  assert.equal(requests.length, 6);
  const { url, init } = requests[0];
  assert.equal(
    url.origin + url.pathname,
    'https://api.vercel.com/v6/deployments'
  );
  assert.equal(url.searchParams.get('projectId'), 'prj_1');
  assert.equal(url.searchParams.get('teamId'), 'team_1');
  assert.equal(url.searchParams.get('sha'), SHA);
  assert.equal(init.headers.authorization, 'Bearer secret');
});

test('fails immediately when the deployment errors', async () => {
  const { options, requests } = harness([
    { deployments: [deployment({ readyState: 'ERROR' })] },
  ]);
  await assert.rejects(waitForDeployment(options), (error) => {
    assert.ok(error instanceof FatalError);
    assert.match(error.message, /dpl_1 failed to build/);
    return true;
  });
  assert.equal(requests.length, 1);
});

test('fails immediately on authorization errors', async () => {
  const { options } = harness([{ status: 403 }]);
  await assert.rejects(waitForDeployment(options), /returned 403/);
});

test('waits for a redeploy after a canceled build, then times out', async () => {
  const canceled = { deployments: [deployment({ readyState: 'CANCELED' })] };
  const { options, requests } = harness(Array(10).fill(canceled));
  await assert.rejects(
    waitForDeployment(options),
    /canceled and not redeployed/
  );
  assert.equal(requests.length, 5);
});

test('a redeploy replaces a canceled build', async () => {
  const { options } = harness([
    { deployments: [deployment({ readyState: 'CANCELED' })] },
    {
      deployments: [
        deployment({ readyState: 'CANCELED' }),
        deployment({ uid: 'dpl_2', createdAt: 2 }),
      ],
    },
  ]);
  assert.equal((await waitForDeployment(options)).uid, 'dpl_2');
});

test('a skipped build resolves to the branch deployment it left serving', async () => {
  const skipped = deployment({
    uid: 'dpl_skipped',
    readyState: 'CANCELED',
    createdAt: 10,
  });
  const serving = deployment({
    uid: 'dpl_serving',
    createdAt: 5,
    meta: { githubCommitSha: BASE_SHA },
  });
  const { options, lookups } = harness([{ deployments: [skipped] }], {
    details: { dpl_skipped: { buildSkipped: true } },
    history: [
      deployment({
        uid: 'dpl_later',
        createdAt: 11,
        meta: { githubCommitSha: BASE_SHA },
      }),
      deployment({
        uid: 'dpl_other_branch',
        createdAt: 6,
        meta: { githubCommitRef: 'other', githubCommitSha: BASE_SHA },
      }),
      deployment({
        uid: 'dpl_older',
        createdAt: 1,
        meta: { githubCommitSha: BASE_SHA },
      }),
      serving,
    ],
  });
  assert.equal((await waitForDeployment(options)).uid, 'dpl_serving');
  const branchQuery = lookups.find((url) => url.searchParams.has('branch'));
  assert.equal(branchQuery.searchParams.get('branch'), 'feature');
  assert.equal(branchQuery.searchParams.get('state'), 'READY');
  assert.equal(branchQuery.searchParams.has('target'), false);
});

test('a skipped production build queries production deployments', async () => {
  const productionTarget = {
    sha: SHA,
    branch: 'main',
    environment: 'production',
  };
  const meta = { githubCommitRef: 'main' };
  const { options, lookups } = harness(
    [
      {
        deployments: [
          deployment({
            uid: 'dpl_skipped',
            target: 'production',
            readyState: 'CANCELED',
            createdAt: 10,
            meta,
          }),
        ],
      },
    ],
    {
      details: {
        dpl_skipped: {
          errorLink:
            'https://vercel.com/docs/monorepos#skipping-unaffected-projects',
        },
      },
      history: [
        deployment({
          uid: 'dpl_prod',
          target: 'production',
          createdAt: 5,
          meta: { ...meta, githubCommitSha: BASE_SHA },
        }),
      ],
    }
  );
  options.target = productionTarget;
  assert.equal((await waitForDeployment(options)).uid, 'dpl_prod');
  const branchQuery = lookups.find((url) => url.searchParams.has('branch'));
  assert.equal(branchQuery.searchParams.get('target'), 'production');
});

test('a skipped build with nothing earlier on the branch fails', async () => {
  const { options } = harness(
    [
      {
        deployments: [
          deployment({ uid: 'dpl_skipped', readyState: 'CANCELED' }),
        ],
      },
    ],
    {
      details: {
        dpl_skipped: {
          buildSkipped: true,
          readyStateReason: 'Ignored Build Step',
        },
      },
    }
  );
  await assert.rejects(waitForDeployment(options), (error) => {
    assert.ok(error instanceof FatalError);
    assert.match(
      error.message,
      /skipped \(Ignored Build Step\) and feature has no earlier/
    );
    return true;
  });
});

test('times out when no deployment appears', async () => {
  const { options } = harness(Array(10).fill({ deployments: [] }));
  await assert.rejects(waitForDeployment(options), /last state: missing/);
});

test('main writes step outputs for the resolved deployment', async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'resolve-deployment-'));
  const eventPath = path.join(dir, 'event.json');
  const outputPath = path.join(dir, 'output');
  fs.writeFileSync(eventPath, JSON.stringify(pullRequest('feature')));
  const { options } = harness([{ deployments: [deployment()] }]);
  delete options.projectId;
  delete options.teamId;
  delete options.token;
  delete options.target;
  delete options.timeoutMs;
  delete options.intervalMs;
  const outputs = await main(
    {
      GITHUB_EVENT_NAME: 'pull_request',
      GITHUB_EVENT_PATH: eventPath,
      GITHUB_OUTPUT: outputPath,
      INPUT_PROJECT_ID: 'prj_1',
      INPUT_TEAM_ID: 'team_1',
      INPUT_TOKEN: 'secret',
      INPUT_TIMEOUT_SECONDS: '60',
      INPUT_INTERVAL_SECONDS: '15',
    },
    options
  );
  assert.deepEqual(outputs, {
    'deployment-id': 'dpl_1',
    'deployment-url': 'https://app-abc.labs.vercel.dev',
    'inspector-url': 'https://vercel.com/team/app/1',
    environment: 'preview',
    sha: SHA,
    branch: 'feature',
  });
  assert.equal(
    fs.readFileSync(outputPath, 'utf8'),
    [
      'deployment-id=dpl_1',
      'deployment-url=https://app-abc.labs.vercel.dev',
      'inspector-url=https://vercel.com/team/app/1',
      'environment=preview',
      `sha=${SHA}`,
      'branch=feature',
      '',
    ].join('\n')
  );
});

'use client';

import {
  animate,
  motion,
  useInView,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from 'motion/react';
import type { JSX } from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';

const ANIMATION_CONFIG = {
  STAGGER_DELAY: 200,
  ANIMATION_DURATION: 1500,
  GRADIENT_FADE_DELAY: 300,
  FADE_OUT_DELAY: 800,
  FADE_OUT_DURATION: 500,
  PAUSE_DURATION: 1000,
  TOTAL_CYCLE_TIME: 4800,
  COLOR_CHANGE_THRESHOLD: { RED: 60, GREEN: 80 },
} as const;

const ANIMATION_LINES = Array.from({ length: 7 }, (_, index) => ({
  id: `line-${index}`,
  delay: index * ANIMATION_CONFIG.STAGGER_DELAY,
}));

export function AgentsVisual(): JSX.Element {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref);
  const shouldReduceMotion = useReducedMotion();
  const [animationKey, setAnimationKey] = useState(0);

  const startAnimationCycle = useCallback(() => {
    if (shouldReduceMotion) return;

    setAnimationKey((prev) => prev + 1);
  }, [shouldReduceMotion]);

  useEffect(() => {
    if (!isInView || shouldReduceMotion) return;

    let intervalId: NodeJS.Timeout;

    const scheduleNextCycle = () => {
      intervalId = setTimeout(() => {
        if (isInView && !shouldReduceMotion) {
          startAnimationCycle();
          scheduleNextCycle();
        }
      }, ANIMATION_CONFIG.TOTAL_CYCLE_TIME);
    };

    startAnimationCycle();
    scheduleNextCycle();

    return () => {
      clearTimeout(intervalId);
    };
  }, [isInView, shouldReduceMotion, startAnimationCycle]);

  return (
    <div
      ref={ref}
      className="aspect-[444/264] w-full max-w-[444px] mx-auto relative overflow-hidden"
      role="img"
      aria-label="Animated workflow visualization showing progressive completion of tasks"
    >
      <div className="w-[calc(100%-10px)] h-full flex flex-col justify-between py-[5px]">
        {ANIMATION_LINES.map((line) => (
          <AnimatedLine
            key={line.id}
            delay={line.delay}
            animationKey={animationKey}
            shouldReduceMotion={shouldReduceMotion}
          />
        ))}
      </div>
      <div className="w-[35%] h-full absolute top-0 left-0 bg-gradient-to-r from-background-200 to-transparent pointer-events-none" />
    </div>
  );
}

interface AnimatedLineProps {
  delay: number;
  animationKey: number;
  shouldReduceMotion: boolean | null;
}

function AnimatedLine({
  delay,
  animationKey,
  shouldReduceMotion,
}: AnimatedLineProps): JSX.Element {
  const width = useMotionValue(0);
  const widthPct = useTransform(width, (v) => `${v}%`);
  const opacity = useMotionValue(1);
  const [hideGradient, setHideGradient] = useState(false);
  const [gradientColor, setGradientColor] = useState<'red' | 'green'>('green');

  useEffect(() => {
    if (shouldReduceMotion) {
      width.set(100);
      opacity.set(1);
      setHideGradient(true);
      setGradientColor('green');
      return;
    }

    setHideGradient(false);
    width.set(0);
    opacity.set(1);

    const widthControls = animate(width, 100, {
      duration: ANIMATION_CONFIG.ANIMATION_DURATION / 1000,
      delay: delay / 1000,
      ease: [0.4, 0.04, 0.04, 1],
    });

    const timeoutIds: NodeJS.Timeout[] = [];

    const unsubscribe = width.on('change', (latest) => {
      if (
        latest > ANIMATION_CONFIG.COLOR_CHANGE_THRESHOLD.RED &&
        latest < ANIMATION_CONFIG.COLOR_CHANGE_THRESHOLD.GREEN
      ) {
        setGradientColor('red');
      }
      if (latest >= ANIMATION_CONFIG.COLOR_CHANGE_THRESHOLD.GREEN) {
        setGradientColor('green');
      }
    });

    void widthControls.finished.then(() => {
      const timeout1 = setTimeout(
        () => setHideGradient(true),
        ANIMATION_CONFIG.GRADIENT_FADE_DELAY
      );
      const timeout2 = setTimeout(
        () => setGradientColor('green'),
        ANIMATION_CONFIG.GRADIENT_FADE_DELAY * 2
      );

      timeoutIds.push(timeout1, timeout2);

      animate(opacity, 0, {
        duration: ANIMATION_CONFIG.FADE_OUT_DURATION / 1000,
        delay: ANIMATION_CONFIG.FADE_OUT_DELAY / 1000,
        ease: [0.4, 0.04, 0.04, 1],
      });
    });

    return () => {
      widthControls.stop();
      unsubscribe();
      timeoutIds.forEach(clearTimeout);
    };
  }, [animationKey, width, opacity, delay, shouldReduceMotion]);

  return (
    <div className="w-full relative text-gray-600">
      <DashedLine />
      <motion.div
        style={{
          width: widthPct,
          opacity: opacity,
        }}
        className="absolute top-0 left-0 overflow-hidden"
      >
        <div className="w-full">
          <SolidLine />
          <GradientLine color={gradientColor} hideGradient={hideGradient} />
        </div>
      </motion.div>
      <Arrow />
    </div>
  );
}

function SolidLine(): JSX.Element {
  return <div className="w-full h-0.5 bg-gray-600" />;
}

function DashedLine(): JSX.Element {
  return (
    <svg
      className="w-full block"
      height="2"
      fill="none"
      viewBox="0 0 432 2"
      aria-hidden="true"
    >
      <path
        stroke="currentColor"
        strokeDasharray="4 4"
        strokeWidth="2"
        d="M432 1H0"
      />
    </svg>
  );
}

interface GradientLineProps {
  hideGradient: boolean;
  color?: 'green' | 'red';
}

function GradientLine({
  hideGradient,
  color = 'red',
}: GradientLineProps): JSX.Element {
  return (
    <div
      className={cn(
        'absolute top-0 right-0 w-12 h-0.5 transition-all duration-300',
        hideGradient && 'opacity-0',
        color === 'green' &&
          'bg-gradient-to-r from-gray-600 via-green-700 to-gray-600',
        color === 'red' &&
          'bg-gradient-to-r from-gray-600 via-red-700 to-gray-600'
      )}
    />
  );
}

function Arrow(): JSX.Element {
  return (
    <svg
      className="absolute top-1/2 -right-2.5 -translate-y-1/2"
      width="10"
      height="12"
      viewBox="0 0 10 12"
      fill="none"
      aria-hidden="true"
    >
      <path fill="currentColor" d="m0 12 10-6L0 0z" />
    </svg>
  );
}

import { execFileSync } from 'node:child_process';
import { mkdtempSync, realpathSync, rmSync } from 'node:fs';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { VercelBuildOutputConfig } from './types.js';
import { VercelBuildOutputAPIBuilder } from './vercel-build-output-api.js';

const BUILD_TIMEOUT = 120_000;

async function write(path: string, contents: string): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, contents, 'utf8');
}

function getFlowFuncDir(workingDir: string): string {
  return join(
    workingDir,
    '.vercel/output/functions/.well-known/workflow/v1/flow.func'
  );
}

function createBuilder(workingDir: string): VercelBuildOutputAPIBuilder {
  const config: VercelBuildOutputConfig = {
    buildTarget: 'vercel-build-output-api',
    workingDir,
    dirs: ['src'],
    stepsBundlePath: join(workingDir, 'unused-steps.mjs'),
    workflowsBundlePath: join(workingDir, 'unused-workflows.mjs'),
    webhookBundlePath: join(workingDir, 'unused-webhook.mjs'),
    suppressCreateManifestLogs: true,
  };
  return new VercelBuildOutputAPIBuilder(config);
}

function executeStep(workingDir: string, stepName: string): string {
  const bundleUrl = pathToFileURL(
    join(getFlowFuncDir(workingDir), 'index.mjs')
  ).href;
  const output = execFileSync(
    process.execPath,
    [
      '--input-type=module',
      '-e',
      `await import(${JSON.stringify(bundleUrl)});
const steps = globalThis[Symbol.for('@workflow/core//registeredSteps')];
const step = [...steps].find(([id]) => id.endsWith(${JSON.stringify(`//${stepName}`)}))?.[1];
if (!step) throw new Error(${JSON.stringify(`${stepName} step was not registered`)});
process.stdout.write(JSON.stringify(await step()));`,
    ],
    { encoding: 'utf8' }
  );
  return JSON.parse(output);
}

/**
 * Minimal stand-in for the `workflow` package so the builder can resolve
 * its runtime imports inside the temp app.
 */
async function writeWorkflowRuntimeStub(workingDir: string): Promise<void> {
  const packageDir = join(workingDir, 'node_modules/workflow');
  await write(
    join(packageDir, 'package.json'),
    JSON.stringify({
      name: 'workflow',
      version: '1.0.0',
      type: 'module',
      exports: {
        './api': './api.js',
        './internal/builtins': './internal/builtins.js',
        './runtime': './runtime.js',
      },
    })
  );
  await write(
    join(packageDir, 'api.js'),
    'export async function resumeWebhook() { return new Response(null, { status: 204 }); }\n'
  );
  await write(
    join(packageDir, 'internal/builtins.js'),
    'export const __workflow_builtins = true;\n'
  );
  await write(
    join(packageDir, 'runtime.js'),
    'export function workflowEntrypoint() { return async function POST() { return new Response(null, { status: 204 }); }; }\n'
  );
}

describe('VercelBuildOutputAPIBuilder ESM output', () => {
  let workingDir: string;

  beforeEach(() => {
    workingDir = mkdtempSync(join(realpathSync(tmpdir()), 'workflow-vercel-'));
  });

  afterEach(() => {
    rmSync(workingDir, { recursive: true, force: true });
  });

  it(
    'executes a bundled CJS dependency that references __dirname at module scope',
    { timeout: BUILD_TIMEOUT },
    async () => {
      await writeWorkflowRuntimeStub(workingDir);

      // google-gax-shaped fixture: a CJS package that computes a path from
      // __dirname at module scope (google-gax/build/src/grpc.js does exactly
      // this), which crashed the whole function at init with
      // `ReferenceError: __dirname is not defined in ES module scope` when
      // inlined into the ESM bundle without the banner shim.
      const packageDir = join(workingDir, 'node_modules/fake-gax');
      await write(
        join(packageDir, 'package.json'),
        JSON.stringify({ name: 'fake-gax', version: '1.0.0', main: 'index.js' })
      );
      await write(
        join(packageDir, 'index.js'),
        `const path = require('path');
// Module-scope __dirname reference, like google-gax's grpc.js.
const protoFilesDir = path.join(__dirname, '..', 'protos');
exports.getProtoFilesDir = () => protoFilesDir;
exports.getFilename = () => __filename;
`
      );
      await write(
        join(workingDir, 'src/workflows/gax.ts'),
        `import { getProtoFilesDir, getFilename } from 'fake-gax';

export async function readDirs(): Promise<string> {
  'use step';
  return [getProtoFilesDir(), getFilename()].every((p) => typeof p === 'string' && p.length > 0)
    ? 'dirs-ok'
    : 'dirs-missing';
}

export async function gaxWorkflow(): Promise<string> {
  'use workflow';
  return readDirs();
}
`
      );

      await createBuilder(workingDir).build();

      // The bundle must be importable under plain Node (this is where the
      // unshimmed bundle throws, before any workflow code runs) and the step
      // must see defined __dirname/__filename values.
      expect(executeStep(workingDir, 'readDirs')).toBe('dirs-ok');

      // The shim is declared exactly once: the inner steps bundle skips its
      // banner when the outer combined pass provides one
      // (skipEsmRequireBanner), so the import bindings don't collide.
      //
      // Note this covers createCombinedBundle and createWebhookBundle. The
      // same banner is also emitted by createWorkflowsBundle's final wrapper,
      // which is not exercised here.
      const bundle = await readFile(
        join(getFlowFuncDir(workingDir), 'index.mjs'),
        'utf8'
      );
      // The import binding is the assertion that matters: a duplicated banner
      // fails at parse time on the redeclared import, before the `var` ever
      // runs.
      expect(
        bundle.match(/import \{ fileURLToPath as __fileURLToPath \}/g)
      ).toHaveLength(1);
      expect(
        bundle.match(/var __dirname = __pathDirname\(__filename\);/g)
      ).toHaveLength(1);

      // The webhook route is a separately deployed function built by the same
      // build() through its own esbuild pass (createWebhookBundle) — a CJS
      // dependency referencing __dirname reachable from it would have crashed
      // the same way, so it needs the shim too.
      const webhookBundle = await readFile(
        join(
          workingDir,
          '.vercel/output/functions/.well-known/workflow/v1/webhook/[token].func/index.mjs'
        ),
        'utf8'
      );
      expect(
        webhookBundle.match(/import \{ fileURLToPath as __fileURLToPath \}/g)
      ).toHaveLength(1);
      expect(
        webhookBundle.match(/var __dirname = __pathDirname\(__filename\);/g)
      ).toHaveLength(1);
    }
  );
});

