import chalk from 'chalk';
import { logger } from '../config/log.js';

interface VercelTeam {
  id: string;
  slug: string;
}

/**
 * Fetch team information from Vercel API
 * Timeout: 5 seconds - falls back to local UI if the request fails or times out
 */
export async function fetchTeamInfo(
  teamId: string,
  authToken: string
): Promise<{ teamSlug: string } | null> {
  try {
    // Create an AbortController with a 5 second timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);

    const response = await fetch(`https://api.vercel.com/v2/teams/${teamId}`, {
      headers: {
        Authorization: `Bearer ${authToken}`,
      },
      signal: controller.signal,
    });

    // Clear the timeout if the request completes successfully
    clearTimeout(timeoutId);

    if (response.status === 401 || response.status === 403) {
      logger.error(
        chalk.red(
          `Authentication failed (${response.status}): Unable to access team information`
        )
      );
      logger.warn(
        chalk.yellow(
          '\nPlease ensure you are logged in and have access to the team:'
        )
      );
      logger.warn(chalk.yellow('  Run `vercel login` to authenticate'));
      return null;
    }

    if (!response.ok) {
      logger.debug(
        `Failed to fetch team info: ${response.status} ${response.statusText}`
      );
      return null;
    }

    const team = (await response.json()) as VercelTeam;
    return {
      teamSlug: team.slug,
    };
  } catch (error) {
    // Handle both timeout and other errors - fall back to local UI
    if (error instanceof Error && error.name === 'AbortError') {
      logger.debug(
        'Vercel API request timed out after 5 seconds, falling back to local UI'
      );
    } else {
      logger.debug(`Error fetching team info: ${error}`);
    }
    return null;
  }
}

/**
 * Get the Vercel dashboard URL for workflows.
 *
 * Format: https://vercel.com/<teamSlug>/<projectSlug>/workflows/runs/<runId>?environment=<env>
 * (the older `/observability/workflows` route is no longer used).
 */
export function getVercelDashboardUrl(
  teamSlug: string,
  projectName: string,
  resource: string,
  id?: string,
  environment = 'production'
): string {
  const base = `https://vercel.com/${teamSlug}/${projectName}/workflows`;
  const env = `environment=${environment}`;

  // Add resource-specific path segments
  if (resource === 'run' && id) {
    return `${base}/runs/${id}?${env}`;
  }
  if (id) {
    return `${base}?${resource}Id=${id}&${env}`;
  }
  return `${base}?${env}`;
}

import {
  EntityConflictError,
  HookNotFoundError,
  ThrottleError,
  WorkflowWorldError,
} from '@workflow/errors';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

// Integration coverage for the retry seam in `createWorkflowRunEvent`: that
// `data.eventType` is actually threaded into `withEventPostRetry`, and that the
// existing 404 → HookNotFoundError mapping still fires *after* the retry loop.
// The unit tests in event-retry.test.ts cover the retry logic in isolation; a
// refactor that wrapped the wrong layer (or passed the wrong event type) would
// keep those green but break here. We mock the v4 wire client so we can assert
// attempt counts and error mapping without standing up a real transport.
const { createV4Mock, createRunStartedV4Mock } = vi.hoisted(() => ({
  createV4Mock: vi.fn(),
  createRunStartedV4Mock: vi.fn(),
}));

vi.mock('./events-v4.js', () => ({
  createWorkflowRunEventV4: createV4Mock,
  createWorkflowRunStartedEventV4: createRunStartedV4Mock,
  getEventV4: vi.fn(),
  getWorkflowRunEventsV4: vi.fn(),
  getEventsByCorrelationIdV4: vi.fn(),
}));

import { AfterCommitError } from './event-retry.js';
import { createWorkflowRunEvent } from './events.js';
import { getDeadline } from './get-deadline.js';

vi.mock('./get-deadline.js', () => ({
  getDeadline: vi.fn(async () => undefined),
}));

const RUN_ID = 'wrun_test';
const CONFIG = { token: 'test-token' };

const stepCompleted = () => ({
  eventType: 'step_completed' as const,
  correlationId: 'step_1',
  specVersion: 2,
  eventData: {
    stepName: 's',
    workflowName: 'w',
    result: new Uint8Array(),
  },
});

const v4Success = () => ({
  event: {
    eventId: 'evnt_1',
    runId: RUN_ID,
    eventType: 'step_completed',
    correlationId: 'step_1',
    specVersion: 2,
    createdAt: '2020-01-01T00:00:00.000Z',
    eventData: { stepName: 's', workflowName: 'w' },
  },
});

describe('createWorkflowRunEvent retry wiring', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    createV4Mock.mockReset();
  });
  afterEach(() => {
    vi.useRealTimers();
  });

  it.each([
    [true, 5],
    [false, 3],
  ])('threads afterStepBody=%s into the step_failed throttle budget', async (afterStepBody, calls) => {
    vi.mocked(getDeadline).mockResolvedValue(new Date(Date.now() + 300_000));
    let attempt = 0;
    createV4Mock.mockImplementation(async () => {
      attempt++;
      if (attempt <= 4) throw new ThrottleError('429', { retryAfter: 14 });
      return v4Success();
    });

    const p = createWorkflowRunEvent(
      RUN_ID,
      {
        eventType: 'step_failed',
        correlationId: 'step_1',
        specVersion: 2,
        eventData: { stepName: 's', error: new Uint8Array() },
      },
      afterStepBody ? { afterStepBody: true } : undefined,
      CONFIG
    ).catch((e: unknown) => e);
    await vi.runAllTimersAsync();
    const result = await p;

    expect(createV4Mock).toHaveBeenCalledTimes(calls);
    expect(ThrottleError.is(result)).toBe(!afterStepBody);
    vi.mocked(getDeadline).mockResolvedValue(undefined);
  });

  it('surfaces a throttled run_started suffix read without re-sending the POST', async () => {
    const throttled = new ThrottleError('429', { retryAfter: 1 });
    createRunStartedV4Mock.mockReset();
    createRunStartedV4Mock.mockRejectedValue(new AfterCommitError(throttled));

    const p = createWorkflowRunEvent(
      RUN_ID,
      { eventType: 'run_started', specVersion: 2 },
      undefined,
      CONFIG
    ).catch((e: unknown) => e);
    await vi.runAllTimersAsync();

    expect(await p).toBe(throttled);
    expect(createRunStartedV4Mock).toHaveBeenCalledTimes(1);
  });

  it('retries a transient 5xx on step_completed and then succeeds', async () => {
    let calls = 0;
    createV4Mock.mockImplementation(async () => {
      calls++;
      if (calls === 1) throw new WorkflowWorldError('boom', { status: 503 });
      return v4Success();
    });

    const p = createWorkflowRunEvent(
      RUN_ID,
      stepCompleted(),
      undefined,
      CONFIG
    );
    await vi.runAllTimersAsync();

    const result = await p;
    expect(result.event).toBeDefined();
    expect(createV4Mock).toHaveBeenCalledTimes(2);
  });

  it('runs an in-band write once on a transient 5xx: a re-send would be refused by its own committed attempt', async () => {
    createV4Mock.mockRejectedValue(
      new WorkflowWorldError('boom', { status: 503 })
    );

    const p = createWorkflowRunEvent(
      RUN_ID,
      stepCompleted(),
      { inBand: true, expectedSeqInBand: 3 },
      CONFIG
    ).catch((error: unknown) => error);
    await vi.runAllTimersAsync();

    expect(WorkflowWorldError.is(await p)).toBe(true);
    expect(createV4Mock).toHaveBeenCalledTimes(1);
  });

  it('still waits out a 429 on an in-band write, which was never processed', async () => {
    let calls = 0;
    createV4Mock.mockImplementation(async () => {
      calls++;
      if (calls === 1) throw new ThrottleError('429', { retryAfter: 1 });
      return v4Success();
    });

    const p = createWorkflowRunEvent(
      RUN_ID,
      stepCompleted(),
      { inBand: true, expectedSeqInBand: 3 },
      CONFIG
    );
    await vi.runAllTimersAsync();

    expect((await p).event).toBeDefined();
    expect(createV4Mock).toHaveBeenCalledTimes(2);
  });

  it('surfaces a retry-time 409 as EntityConflictError', async () => {
    let calls = 0;
    createV4Mock.mockImplementation(async () => {
      calls++;
      if (calls === 1) throw new WorkflowWorldError('boom', { status: 503 });
      throw new EntityConflictError('already completed');
    });

    const p = createWorkflowRunEvent(
      RUN_ID,
      stepCompleted(),
      undefined,
      CONFIG
    ).catch((e) => e);
    await vi.runAllTimersAsync();

    const err = await p;
    expect(EntityConflictError.is(err)).toBe(true);
    expect(createV4Mock).toHaveBeenCalledTimes(2);
  });

  it('still maps a hook_disposed 404 to HookNotFoundError, after the retry loop, without retrying', async () => {
    createV4Mock.mockImplementation(async () => {
      throw new WorkflowWorldError('not found', { status: 404 });
    });

    await expect(
      createWorkflowRunEvent(
        RUN_ID,
        { eventType: 'hook_disposed', correlationId: 'hook_1', specVersion: 2 },
        undefined,
        CONFIG
      )
    ).rejects.toBeInstanceOf(HookNotFoundError);
    // 404 is definitive → one attempt; the mapping wraps the retry loop.
    expect(createV4Mock).toHaveBeenCalledTimes(1);
  });

  it('does not retry an excluded event type (step_started) even on a 5xx', async () => {
    createV4Mock.mockImplementation(async () => {
      throw new WorkflowWorldError('boom', { status: 503 });
    });

    await expect(
      createWorkflowRunEvent(
        RUN_ID,
        { eventType: 'step_started', correlationId: 'step_1', specVersion: 2 },
        undefined,
        CONFIG
      )
    ).rejects.toBeInstanceOf(WorkflowWorldError);
    expect(createV4Mock).toHaveBeenCalledTimes(1);
  });
});

import {
  createServer,
  type IncomingMessage,
  type ServerResponse,
} from 'node:http';
import type { AddressInfo } from 'node:net';
import { StreamError } from '@workflow/errors';
import { buildConnector } from 'undici';
import { describe, expect, it, vi } from 'vitest';
import * as httpClient from './http-client.js';
import {
  createStreamer,
  encodeMultiChunks,
  writeStreamSessionOverHttp,
} from './streamer.js';

type ReceivedAppend = { request: IncomingMessage; body?: Buffer };

async function withAppendServer(
  reply: (res: ServerResponse, body: Buffer, attempt: number) => void,
  test: (context: {
    dispatcher: ReturnType<typeof httpClient.createStreamDispatcher>;
    requests: ReceivedAppend[];
    server: ReturnType<typeof createServer>;
  }) => Promise<void>
) {
  const requests: ReceivedAppend[] = [];
  const server = createServer((req, res) => {
    const received: ReceivedAppend = { request: req };
    requests.push(received);
    const attempt = requests.length;
    const chunks: Buffer[] = [];
    req.on('error', () => {});
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => {
      received.body = Buffer.concat(chunks);
      reply(res, received.body, attempt);
    });
  });
  // One connection also proves a discarded 429 does not hold up the retry.
  const dispatcher = httpClient.createStreamDispatcher(
    httpClient.STREAM_RETRY_OPTIONS,
    { connections: 1 }
  );
  vi.spyOn(httpClient, 'getStreamDispatcher').mockReturnValue(dispatcher);
  try {
    await new Promise<void>((resolve) =>
      server.listen(0, '127.0.0.1', resolve)
    );
    const origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
    vi.stubEnv('VERCEL_WORKFLOW_SERVER_URL', origin);
    vi.stubEnv('WORKFLOW_NODE_HTTP', '0');
    await test({ dispatcher, requests, server });
  } finally {
    await dispatcher.destroy();
    server.closeAllConnections();
    await new Promise<void>((resolve) => server.close(() => resolve()));
    vi.restoreAllMocks();
    vi.unstubAllEnvs();
  }
}

/** Bound a lifecycle assertion while always allowing the fixture to clean up. */
async function within<T>(promise: Promise<T>): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(
          () => reject(new Error('lifecycle did not settle')),
          2000
        );
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
}

// Reduced from https://github.com/vercel/workflow/issues/4628. Exercise the
// production streamer and dispatcher through real fetch and a loopback server.
describe('HTTP append retry integration', () => {
  it('resends the complete body when a refused connection recovers', async () => {
    await withAppendServer(
      (res) => res.end(),
      async ({ requests, server }) => {
        const port = (server.address() as AddressInfo).port;
        await new Promise<void>((resolve) => server.close(() => resolve()));
        const connect = buildConnector({});
        let refused = 0;
        const dispatcher = httpClient.createStreamDispatcher(
          httpClient.STREAM_RETRY_OPTIONS,
          {
            connect(options, callback) {
              connect(options, (error, socket) => {
                if (error) {
                  refused++;
                  // Reopen only after a real failed connect, avoiding a timer race.
                  server.listen(port, '127.0.0.1', () => callback(error, null));
                } else callback(null, socket);
              });
            },
          }
        );
        vi.spyOn(httpClient, 'getStreamDispatcher').mockReturnValue(dispatcher);
        try {
          await createStreamer().streams.write('wrun_test', 'data', 'Hello');
          expect(refused).toBe(1);
          expect(requests.map(({ body }) => body)).toEqual([
            Buffer.from('Hello'),
          ]);
        } finally {
          await dispatcher.destroy();
        }
      }
    );
  });

  it('resends complete UTF-8 bytes after the first body is consumed', async () => {
    const payload = 'Hello, 世界 👋 Привет';
    const expected = Buffer.from(payload);
    const saved: Buffer[] = [];
    await withAppendServer(
      (res, body, attempt) => {
        if (attempt === 1) res.writeHead(429, { 'Retry-After': '1' }).end();
        else {
          saved.push(body);
          res.end();
        }
      },
      async ({ requests }) => {
        await createStreamer().streams.write('wrun_test', 'data', payload);
        expect(requests.map(({ body }) => body?.equals(expected))).toEqual([
          true,
          true,
        ]);
        expect(saved.map((body) => body.equals(expected))).toEqual([true]);
      }
    );
  });

  it.each([
    'writeMulti',
    'session',
  ] as const)('retries individual %s pages without resending accepted pages', async (mode) => {
    const chunks = ['first', new Uint8Array([0, 255]), '世界'];
    const pages = [
      Buffer.from(encodeMultiChunks(chunks.slice(0, 2))),
      Buffer.from(encodeMultiChunks(chunks.slice(2))),
    ];
    const saved: Buffer[] = [];
    const onRequestDispatched = vi.fn();
    await withAppendServer(
      (res, body, attempt) => {
        if (attempt === 2) {
          res.writeHead(429, { 'Retry-After': '1' }).end();
        } else {
          saved.push(body);
          res.end();
        }
      },
      async ({ requests }) => {
        vi.stubEnv('WORKFLOW_MAX_CHUNKS_PER_REQUEST', '2');
        if (mode === 'session') {
          await writeStreamSessionOverHttp(
            'wrun_test',
            'data',
            chunks,
            undefined,
            undefined,
            onRequestDispatched
          );
          expect(onRequestDispatched).toHaveBeenCalledTimes(1);
        } else {
          const { writeMulti } = createStreamer().streams;
          if (!writeMulti)
            throw new Error('HTTP streamer must implement writeMulti');
          await writeMulti('wrun_test', 'data', chunks);
        }
        expect(requests.map(({ body }) => body)).toEqual([
          pages[0],
          pages[1],
          pages[1],
        ]);
        expect(saved).toEqual(pages);
        expect(
          requests.every(
            ({ request }) => request.headers['x-stream-multi'] === 'true'
          )
        ).toBe(true);
      }
    );
  });

  it('preserves a Buffer view when the caller changes it between attempts', async () => {
    const payload = Buffer.from('!original?').subarray(1, -1);
    const saved: Buffer[] = [];
    await withAppendServer(
      (res, body, attempt) => {
        if (attempt === 1) {
          payload.fill(0);
          res.writeHead(429, { 'Retry-After': '1' }).end();
        } else {
          saved.push(body);
          res.end();
        }
      },
      async ({ requests }) => {
        await createStreamer().streams.write('wrun_test', 'data', payload);
        expect(requests.map(({ body }) => body?.toString())).toEqual([
          'original',
          'original',
        ]);
        expect(saved.map((body) => body.toString())).toEqual(['original']);
      }
    );
  });

  it.each([
    '500',
    'socket reset',
  ])('does not duplicate a saved append followed by %s', async (failure) => {
    const saved: Buffer[] = [];
    await withAppendServer(
      (res, body) => {
        saved.push(body);
        if (failure === '500') res.writeHead(500).end('saved, but failed');
        else res.destroy();
      },
      async ({ requests }) => {
        await expect(
          createStreamer().streams.write('wrun_test', 'data', 'Hello')
        ).rejects.toBeInstanceOf(StreamError);
        expect(requests).toHaveLength(1);
        expect(saved).toEqual([Buffer.from('Hello')]);
      }
    );
  });

  it('surfaces a firewall challenge without retrying it', async () => {
    await withAppendServer(
      (res) =>
        res
          .writeHead(429, {
            'Retry-After': '1',
            'x-vercel-mitigated': 'challenge',
          })
          .end('challenge'),
      async ({ requests }) => {
        await expect(
          createStreamer().streams.write('wrun_test', 'data', 'Hello')
        ).rejects.toMatchObject({ code: 'STREAM_ERROR', status: 429 });
        expect(requests).toHaveLength(1);
      }
    );
  });

  it('releases an unfinished 429 body before retrying on a single-connection pool', async () => {
    const rejectedClosed = Promise.withResolvers<void>();
    await withAppendServer(
      (res, _body, attempt) => {
        if (attempt === 1) {
          res.on('close', rejectedClosed.resolve);
          res.writeHead(429, { 'Retry-After': '1' });
          res.write('never ending diagnostic');
        } else res.end();
      },
      async ({ requests }) => {
        await within(
          createStreamer().streams.write('wrun_test', 'data', 'Hello')
        );
        await within(rejectedClosed.promise);
        expect(requests).toHaveLength(2);
      }
    );
  });

  it.each([
    'write',
    'writeMulti',
    'session',
  ] as const)('leaves a custom dispatcher in control of %s retries', async (mode) => {
    await withAppendServer(
      (res) => res.writeHead(429, { 'Retry-After': '1' }).end('custom policy'),
      async ({ dispatcher, requests }) => {
        vi.restoreAllMocks();
        const config = { dispatcher };
        const streams = createStreamer(config).streams;
        if (!streams.writeMulti)
          throw new Error('HTTP streamer must implement writeMulti');
        const result =
          mode === 'session'
            ? writeStreamSessionOverHttp('wrun_test', 'data', ['Hello'], config)
            : mode === 'writeMulti'
              ? streams.writeMulti('wrun_test', 'data', ['Hello'])
              : streams.write('wrun_test', 'data', 'Hello');
        await expect(result).rejects.toMatchObject({
          code: 'STREAM_ERROR',
          status: 429,
        });
        expect(requests).toHaveLength(1);
      }
    );
  });

  it('retains bodyless close retries for a 503', async () => {
    await withAppendServer(
      (res, _body, attempt) => {
        res
          .writeHead(attempt === 1 ? 503 : 200, { 'Retry-After': '0.001' })
          .end();
      },
      async ({ requests }) => {
        const closeDispatcher = httpClient.createStreamDispatcher(
          httpClient.STREAM_CLOSE_RETRY_OPTIONS
        );
        vi.spyOn(httpClient, 'getStreamCloseDispatcher').mockReturnValue(
          closeDispatcher
        );
        try {
          await createStreamer().streams.close('wrun_test', 'data');
          expect(requests).toHaveLength(2);
          expect(
            requests.every(
              ({ request, body }) =>
                request.headers['x-stream-done'] === 'true' &&
                body?.length === 0
            )
          ).toBe(true);
        } finally {
          await closeDispatcher.destroy();
        }
      }
    );
  });
});

import {
  EntityConflictError,
  RunExpiredError,
  StreamError,
  ThrottleError,
  TooEarlyError,
  WorkflowWorldError,
} from '@workflow/errors';
import { EventTypeSchema } from '@workflow/world';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import {
  AfterCommitError,
  EVENT_RETRY_ELIGIBILITY,
  isRetryableEventPostError,
  MAX_EVENT_POST_RETRIES,
  recordsStepOutcome,
  THROTTLE_DEADLINE_RESERVE_MS,
  THROTTLE_RETRY_BUDGET_MS,
  THROTTLE_RETRY_MAX_BUDGET_MS,
  withEventPostRetry,
} from './event-retry.js';
import { getDeadline } from './get-deadline.js';

vi.mock('./get-deadline.js', () => ({
  getDeadline: vi.fn(async () => undefined),
}));

const transportErr = (code: string) =>
  Object.assign(new Error(`transport ${code}`), { code });

// undici `fetch` wraps low-level failures in a TypeError whose `cause` carries
// the real code — the classifier must walk the cause chain.
const fetchFailed = (code: string) =>
  Object.assign(new TypeError('fetch failed'), {
    cause: Object.assign(new Error('underlying'), { code }),
  });

describe('EVENT_RETRY_ELIGIBILITY', () => {
  it('classifies every world event type (no gaps)', () => {
    for (const type of EventTypeSchema.options) {
      const policy = EVENT_RETRY_ELIGIBILITY[type];
      expect(policy, `missing policy for ${type}`).toBeDefined();
      expect(typeof policy.retryable).toBe('boolean');
      expect(policy.reason.length).toBeGreaterThan(0);
    }
  });

  it('marks idempotent-on-retry events retryable', () => {
    for (const type of [
      'run_created',
      'run_started',
      'run_completed',
      'run_failed',
      'run_cancelled',
      'attr_set',
      'step_created',
      'step_completed',
      'step_failed',
      'wait_created',
      'wait_completed',
      'hook_created',
      'hook_disposed',
    ] as const) {
      expect(EVENT_RETRY_ELIGIBILITY[type].retryable, type).toBe(true);
    }
  });

  it('excludes events that are unsafe to blindly retry', () => {
    // step_started double-increments attempt; step_retrying / hook_received
    // append a duplicate event row; hook_conflict is server-originated.
    for (const type of [
      'step_started',
      'step_retrying',
      'hook_received',
      'hook_conflict',
    ] as const) {
      expect(EVENT_RETRY_ELIGIBILITY[type].retryable, type).toBe(false);
    }
  });
});

describe('isRetryableEventPostError', () => {
  it('retries transient 5xx', () => {
    for (const status of [500, 502, 503, 504]) {
      expect(
        isRetryableEventPostError(new WorkflowWorldError('boom', { status }))
      ).toBe(true);
    }
  });

  it('does not retry 4xx definitive responses', () => {
    for (const status of [400, 404]) {
      expect(
        isRetryableEventPostError(new WorkflowWorldError('nope', { status }))
      ).toBe(false);
    }
  });

  it('does not retry server-considered conflicts/terminal/too-early/throttle', () => {
    expect(isRetryableEventPostError(new EntityConflictError('409'))).toBe(
      false
    );
    expect(isRetryableEventPostError(new RunExpiredError('410'))).toBe(false);
    expect(isRetryableEventPostError(new TooEarlyError('425'))).toBe(false);
    expect(isRetryableEventPostError(new ThrottleError('429'))).toBe(false);
  });

  it('retries a body-parse failure (write may have landed)', () => {
    expect(
      isRetryableEventPostError(
        new WorkflowWorldError('parse', { code: 'PARSE_ERROR' })
      )
    ).toBe(true);
  });

  it('retries a TRANSPORT failure from either transport', () => {
    // The one code that lets this policy serve HTTP and WS alike: `utils.ts`
    // sets it for a `fetch` that failed transiently, `events-v4.ts` for a WS
    // socket that died or produced no correlatable reply. Both mean the write
    // was never acked.
    expect(
      isRetryableEventPostError(
        new WorkflowWorldError('POST … transport failure: socket hang up', {
          code: 'TRANSPORT',
        })
      )
    ).toBe(true);
  });

  it('retries a TRANSPORT failure whose cause carries no known marker', () => {
    // Why the code has to be read directly rather than left to the cause walk:
    // a WS failure's cause is a `WsTransportError`, which carries none of the
    // undici/Node markers in TRANSIENT_CODES.
    const cause = Object.assign(new Error('connection closed (code 1006)'), {
      name: 'WsTransportError',
    });
    expect(isRetryableEventPostError(cause)).toBe(false);
    expect(
      isRetryableEventPostError(
        new WorkflowWorldError('POST … transport failure: connection closed', {
          code: 'TRANSPORT',
          cause,
        })
      )
    ).toBe(true);
  });

  it('does not retry a TIMEOUT that is a caller-requested abort', () => {
    // `utils.ts` maps both a missed deadline and an `AbortError` onto
    // `code: 'TIMEOUT'`, so — unlike TRANSPORT — that code must not be a
    // blanket yes; it falls through to the marker walk, which tells them apart.
    expect(
      isRetryableEventPostError(
        new WorkflowWorldError('request aborted', {
          code: 'TIMEOUT',
          cause: Object.assign(new Error('aborted'), { name: 'AbortError' }),
        })
      )
    ).toBe(false);
    expect(
      isRetryableEventPostError(
        new WorkflowWorldError('request timed out', {
          code: 'TIMEOUT',
          cause: Object.assign(new Error('timed out'), {
            name: 'TimeoutError',
          }),
        })
      )
    ).toBe(true);
  });

  it('retries raw transport errors by code', () => {
    for (const code of [
      'ECONNRESET',
      'ETIMEDOUT',
      'UND_ERR_SOCKET',
      'UND_ERR_REQ_RETRY',
      'UND_ERR_HEADERS_TIMEOUT',
    ]) {
      expect(isRetryableEventPostError(transportErr(code)), code).toBe(true);
    }
  });

  it('retries transport errors hidden under a `fetch failed` cause', () => {
    expect(isRetryableEventPostError(fetchFailed('UND_ERR_SOCKET'))).toBe(true);
  });

  it('retries our own timeout (TimeoutError) but not an external abort (AbortError)', () => {
    // Self-deadline via AbortSignal.timeout → TimeoutError → ambiguous, retry.
    expect(
      isRetryableEventPostError(
        Object.assign(new Error('timed out'), { name: 'TimeoutError' })
      )
    ).toBe(true);
    // Caller-requested cancellation surfaces as AbortError → must NOT be retried.
    expect(
      isRetryableEventPostError(
        Object.assign(new Error('aborted'), { name: 'AbortError' })
      )
    ).toBe(false);
    // Also when wrapped by makeRequest as a WorkflowWorldError(cause).
    expect(
      isRetryableEventPostError(
        new WorkflowWorldError('request aborted', {
          cause: Object.assign(new Error('aborted'), { name: 'AbortError' }),
        })
      )
    ).toBe(false);
  });

  it.each([
    'AbortError',
    'ABORT_ERR',
    'UND_ERR_ABORTED',
    'ERR_HTTP2_STREAM_CANCEL',
  ])('does not retry STREAM_ERROR wrapping cancellation marker %s', (marker) => {
    const cause = Object.assign(new Error('cancelled'), {
      code: marker,
      name: marker,
      cause: transportErr('ECONNRESET'),
    });
    expect(
      isRetryableEventPostError(
        new StreamError('stream failed', {
          cause: new Error('wrapper', { cause }),
        })
      )
    ).toBe(false);
  });

  it('retries STREAM_ERROR wrapping an internal timeout', () => {
    expect(
      isRetryableEventPostError(
        new StreamError('stream timed out', {
          cause: new DOMException('deadline', 'TimeoutError'),
        })
      )
    ).toBe(true);
  });

  it('does not retry an unclassified error', () => {
    expect(isRetryableEventPostError(new Error('something else'))).toBe(false);
  });
});

describe('withEventPostRetry', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });
  afterEach(() => {
    vi.useRealTimers();
  });

  it('retries a retryable event past a transient blip and returns the result', async () => {
    let calls = 0;
    const fn = vi.fn(async () => {
      calls++;
      if (calls === 1) throw transportErr('ECONNRESET');
      return 'ok';
    });

    const p = withEventPostRetry(fn, 'step_completed');
    await vi.runAllTimersAsync();

    await expect(p).resolves.toBe('ok');
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it('surfaces a 409 that appears on a retry (original landed)', async () => {
    let calls = 0;
    const fn = vi.fn(async () => {
      calls++;
      if (calls === 1) throw transportErr('ECONNRESET');
      // The first attempt actually landed; the retry observes the conflict.
      throw new EntityConflictError('already completed');
    });

    const p = withEventPostRetry(fn, 'step_completed').catch((e) => e);
    await vi.runAllTimersAsync();

    const err = await p;
    expect(EntityConflictError.is(err)).toBe(true);
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it('gives up after MAX_EVENT_POST_RETRIES and throws the last error', async () => {
    const fn = vi.fn(async () => {
      throw transportErr('ECONNRESET');
    });

    const p = withEventPostRetry(fn, 'step_completed').catch((e) => e);
    await vi.runAllTimersAsync();

    const err = await p;
    expect((err as { code?: string }).code).toBe('ECONNRESET');
    expect(fn).toHaveBeenCalledTimes(MAX_EVENT_POST_RETRIES + 1);
  });

  it('does not retry a definitive failure even for a retryable event', async () => {
    const fn = vi.fn(async () => {
      throw new WorkflowWorldError('bad request', { status: 400 });
    });

    await expect(withEventPostRetry(fn, 'step_completed')).rejects.toThrow();
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('does not retry an excluded event (step_started — protects the attempt counter)', async () => {
    const fn = vi.fn(async () => {
      throw transportErr('ECONNRESET');
    });

    await expect(withEventPostRetry(fn, 'step_started')).rejects.toThrow();
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('does not retry an excluded event (hook_received — avoids double-delivery)', async () => {
    const fn = vi.fn(async () => {
      throw transportErr('ECONNRESET');
    });

    await expect(withEventPostRetry(fn, 'hook_received')).rejects.toThrow();
    expect(fn).toHaveBeenCalledTimes(1);
  });

  describe('throttle (429) in-process retry', () => {
    it('retries a ThrottleError after its retryAfter and returns the result', async () => {
      let calls = 0;
      const fn = vi.fn(async () => {
        calls++;
        if (calls === 1) throw new ThrottleError('429', { retryAfter: 14 });
        return 'ok';
      });

      const p = withEventPostRetry(fn, 'step_completed');
      // Not yet retried before the server's requested wait has elapsed.
      await vi.advanceTimersByTimeAsync(13_000);
      expect(fn).toHaveBeenCalledTimes(1);
      await vi.advanceTimersByTimeAsync(1_000);

      await expect(p).resolves.toBe('ok');
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('applies to eligibility-excluded events too (429 is a definitive no-write)', async () => {
      let calls = 0;
      const fn = vi.fn(async () => {
        calls++;
        if (calls === 1) throw new ThrottleError('429', { retryAfter: 1 });
        return 'ok';
      });

      const p = withEventPostRetry(fn, 'step_started');
      await vi.runAllTimersAsync();

      await expect(p).resolves.toBe('ok');
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('defaults to a 1s wait when the 429 carries no retryAfter', async () => {
      let calls = 0;
      const fn = vi.fn(async () => {
        calls++;
        if (calls === 1) throw new ThrottleError('429');
        return 'ok';
      });

      const p = withEventPostRetry(fn, 'run_started');
      await vi.advanceTimersByTimeAsync(1_000);

      await expect(p).resolves.toBe('ok');
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('surfaces the ThrottleError once the cumulative wait budget is exhausted', async () => {
      const fn = vi.fn(async () => {
        throw new ThrottleError('429', { retryAfter: 14 });
      });

      const p = withEventPostRetry(fn, 'step_completed').catch((e) => e);
      await vi.runAllTimersAsync();

      const err = await p;
      expect(ThrottleError.is(err)).toBe(true);
      // 14s per attempt against a 30s budget: 14 + 14 fits, a third doesn't.
      expect(fn).toHaveBeenCalledTimes(3);
    });

    it('surfaces immediately when retryAfter alone exceeds the budget', async () => {
      const fn = vi.fn(async () => {
        throw new ThrottleError('429', {
          retryAfter: THROTTLE_RETRY_BUDGET_MS / 1000 + 1,
        });
      });

      await expect(withEventPostRetry(fn, 'step_completed')).rejects.toThrow(
        '429'
      );
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('never re-sends a POST whose failure came after it committed', async () => {
      const throttled = new ThrottleError('429', { retryAfter: 1 });
      const fn = vi.fn(async () => {
        throw new AfterCommitError(throttled);
      });

      const err = await withEventPostRetry(fn, 'run_started').catch((e) => e);

      expect(err).toBeInstanceOf(AfterCommitError);
      expect((err as AfterCommitError).error).toBe(throttled);
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('does not consume the transient retry allowance', async () => {
      // A throttle wait followed by transient blips: the transient counter
      // still permits MAX_EVENT_POST_RETRIES retries.
      let calls = 0;
      const fn = vi.fn(async () => {
        calls++;
        if (calls === 1) throw new ThrottleError('429', { retryAfter: 1 });
        if (calls <= 1 + MAX_EVENT_POST_RETRIES)
          throw transportErr('ECONNRESET');
        return 'ok';
      });

      const p = withEventPostRetry(fn, 'step_completed');
      await vi.runAllTimersAsync();

      await expect(p).resolves.toBe('ok');
      expect(fn).toHaveBeenCalledTimes(2 + MAX_EVENT_POST_RETRIES);
    });
  });

  describe('throttle budget by what giving up would lose', () => {
    const deadlineIn = (ms: number) =>
      vi.mocked(getDeadline).mockResolvedValue(new Date(Date.now() + ms));
    afterEach(() => {
      vi.mocked(getDeadline).mockResolvedValue(undefined);
    });
    const alwaysThrottled = (retryAfter: number) =>
      vi.fn(async () => {
        throw new ThrottleError('429', { retryAfter });
      });

    it('gives only execution-only step outcomes the invocation budget', () => {
      expect(
        EventTypeSchema.options
          .filter((type) => recordsStepOutcome(type))
          .sort()
      ).toEqual(['step_completed', 'step_retrying']);
    });

    it('keeps a step outcome waiting until the invocation deadline', async () => {
      deadlineIn(300_000);
      const fn = alwaysThrottled(14);

      const p = withEventPostRetry(fn, 'step_completed').catch((e) => e);
      await vi.runAllTimersAsync();

      expect(ThrottleError.is(await p)).toBe(true);
      // Every 14s wait that ends before (deadline - reserve) is taken.
      const waits = Math.floor(
        (300_000 - THROTTLE_DEADLINE_RESERVE_MS) / 14_000
      );
      expect(fn).toHaveBeenCalledTimes(waits + 1);
    });

    it('resends a step outcome past the 30s budget and returns', async () => {
      deadlineIn(300_000);
      let calls = 0;
      const fn = vi.fn(async () => {
        calls++;
        if (calls <= 4) throw new ThrottleError('429', { retryAfter: 12 });
        return 'ok';
      });

      const p = withEventPostRetry(fn, 'step_completed');
      await vi.runAllTimersAsync();

      await expect(p).resolves.toBe('ok');
      expect(fn).toHaveBeenCalledTimes(5);
    });

    it.each([
      'step_started',
      'step_failed',
      'run_started',
      'run_completed',
      'hook_received',
    ] as const)('keeps %s on the 30s budget', async (eventType) => {
      deadlineIn(300_000);
      const fn = alwaysThrottled(14);

      const p = withEventPostRetry(fn, eventType).catch((e) => e);
      await vi.runAllTimersAsync();

      expect(ThrottleError.is(await p)).toBe(true);
      expect(fn).toHaveBeenCalledTimes(3);
    });

    it('falls back to the 30s budget when the deadline is unknown', async () => {
      const fn = alwaysThrottled(14);

      const p = withEventPostRetry(fn, 'step_completed').catch((e) => e);
      await vi.runAllTimersAsync();

      expect(ThrottleError.is(await p)).toBe(true);
      expect(fn).toHaveBeenCalledTimes(3);
    });

    it('never sleeps past the deadline, even within the 30s budget', async () => {
      deadlineIn(THROTTLE_DEADLINE_RESERVE_MS + 5_000);
      const fn = alwaysThrottled(10);

      await expect(withEventPostRetry(fn, 'step_started')).rejects.toThrow(
        '429'
      );
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('caps the wait when the deadline is implausibly far', async () => {
      deadlineIn(24 * 60 * 60_000);
      const fn = alwaysThrottled(60);

      const p = withEventPostRetry(fn, 'step_retrying').catch((e) => e);
      await vi.runAllTimersAsync();

      expect(ThrottleError.is(await p)).toBe(true);
      expect(fn).toHaveBeenCalledTimes(
        Math.floor(THROTTLE_RETRY_MAX_BUDGET_MS / 60_000) + 1
      );
    });

    it('gives a step_failed recorded after the body ran the invocation budget', async () => {
      deadlineIn(300_000);
      const fn = alwaysThrottled(14);

      const p = withEventPostRetry(fn, 'step_failed', {
        afterStepBody: true,
      }).catch((e) => e);
      await vi.runAllTimersAsync();

      expect(ThrottleError.is(await p)).toBe(true);
      const waits = Math.floor(
        (300_000 - THROTTLE_DEADLINE_RESERVE_MS) / 14_000
      );
      expect(fn).toHaveBeenCalledTimes(waits + 1);
    });

    it('keeps a batch on the 30s budget whatever its first event', async () => {
      deadlineIn(300_000);
      const fn = alwaysThrottled(14);

      const p = withEventPostRetry(fn, 'step_completed', {
        batchIdempotent: true,
      }).catch((e) => e);
      await vi.runAllTimersAsync();

      expect(ThrottleError.is(await p)).toBe(true);
      expect(fn).toHaveBeenCalledTimes(3);
    });
  });

  describe('idempotentHookResume opt-in', () => {
    it('retries an atomic hook resume (resumeId + digest) past an ECONNRESET', async () => {
      // The (runId, resumeId) claim makes the write idempotent-on-retry: a
      // retry whose original landed converges on the same canonical event.
      let calls = 0;
      const fn = vi.fn(async () => {
        calls++;
        if (calls === 1) throw transportErr('ECONNRESET');
        return 'ok';
      });

      const p = withEventPostRetry(fn, 'hook_received', {
        idempotentHookResume: true,
      });
      await vi.runAllTimersAsync();

      await expect(p).resolves.toBe('ok');
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('keeps plain hook_received single-attempt when the opt-in is absent', async () => {
      const fn = vi.fn(async () => {
        throw transportErr('ECONNRESET');
      });

      await expect(
        withEventPostRetry(fn, 'hook_received', {})
      ).rejects.toThrow();
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('keeps an incomplete idempotency shape single-attempt (opt-in false)', async () => {
      // The caller computes the opt-in from resumeId AND digest presence —
      // resumeId-only / digest-only writes arrive here with false.
      const fn = vi.fn(async () => {
        throw transportErr('ECONNRESET');
      });

      await expect(
        withEventPostRetry(fn, 'hook_received', {
          idempotentHookResume: false,
        })
      ).rejects.toThrow();
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('never retries a definitive response, even with the opt-in', async () => {
      const fn = vi.fn(async () => {
        throw new WorkflowWorldError('digest reuse', { status: 422 });
      });

      await expect(
        withEventPostRetry(fn, 'hook_received', {
          idempotentHookResume: true,
        })
      ).rejects.toThrow();
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('does not widen retries for other event types', async () => {
      const fn = vi.fn(async () => {
        throw transportErr('ECONNRESET');
      });

      await expect(
        withEventPostRetry(fn, 'step_started', {
          idempotentHookResume: true,
        })
      ).rejects.toThrow();
      expect(fn).toHaveBeenCalledTimes(1);
    });
  });
});

